// Segment obstruction is shared by detection and the rendered world objects.
export function machineHuntSightBlocked(a,b,obstacles){const vx=b.x-a.x,vy=b.y-a.y,length=vx*vx+vy*vy||1;return obstacles.some(o=>{const t=clamp(((o.x-a.x)*vx+(o.y-a.y)*vy)/length,0,1),dx=a.x+vx*t-o.x,dy=a.y+vy*t-o.y;return dx*dx+dy*dy<o.r*o.r});}
export function machineHuntDetection(level,distance,sight,inCover,hidden,blocked,dt){const gain=distance<sight&&!blocked?(inCover&&hidden?15:distance<sight*.5?144:78):-48;const lose=level>=100&&(blocked||(inCover&&distance>92))?66:0;return clamp(level+(gain-lose)*dt,0,100);}
export function machineHuntAimTarget(robots,hero,automatic=false){const eligible=robots.filter(r=>!r.dead&&(!automatic||r.detect>=100)&&Math.hypot(r.x-hero.x,r.y-hero.y)<260);return eligible.length?eligible.reduce((a,b)=>Math.hypot(a.x-hero.x,a.y-hero.y)<Math.hypot(b.x-hero.x,b.y-hero.y)?a:b):null;}
export function machineHuntLeadAngle(hero,target,jitterX=0,jitterY=0){const d=Math.hypot(target.x-hero.x,target.y-hero.y),flight=Math.min(.4,d/168),dt=target.stepDt||1/60,vx=(target.x-(target.prevX??target.x))/dt,vy=(target.y-(target.prevY??target.y))/dt;return Math.atan2(target.y+vy*flight*.5+jitterY-hero.y,target.x+vx*flight*.5+jitterX-hero.x);}
