export function machineHuntAdvanceMigration(migration,meters,dt){if(migration.phase==='calm'){if(meters>=migration.next){migration.phase='warn';migration.timer=0;return 'warning'}}else if(migration.phase==='warn'){migration.timer+=dt;if(migration.timer>=4){migration.phase='live';migration.timer=0;return 'stampede'}}else{migration.timer+=dt;if(migration.timer>=520/60){migration.phase='calm';migration.timer=0;migration.next=meters+300;return 'passed'}}return null}
