export function machineHuntTier(power){return power>=50?4:power>=30?3:power>=16?2:power>=6?1:0}
export const machineHuntTierColors=['#d9c58a','#cfe8ff','#ff9a4a','#ffb347','#7ef0ff'];
export function machineHuntArrowHitsRobot(arrow,robot){const halfWidth=[12,16,20,30][robot.kind],halfHeight=[16,15,17,22][robot.kind];return Math.abs(arrow.x-robot.x)<halfWidth&&Math.abs(arrow.y-robot.y)<halfHeight}
