export function machineHuntHasNearbyAlert(robots,hero){return robots.some(r=>!r.dead&&r.detect>=100&&Math.hypot(r.x-hero.x,r.y-hero.y)<260)}
export function machineHuntRetreatCover(grass,trees,hero,robots){const alerted=robots.filter(r=>!r.dead&&r.detect>=100&&Math.hypot(r.x-hero.x,r.y-hero.y)<260),covers=[...grass,...trees],risk=c=>Math.hypot(c.x-hero.x,c.y-hero.y)+2*alerted.reduce((sum,r)=>sum+Math.max(0,240-Math.hypot(c.x-r.x,c.y-r.y)),0);return covers.length?covers.reduce((best,c)=>risk(c)<risk(best)?c:best):null}
