export function drawMachineHuntCorpse(c,corpse){const w=[16,24,32,52][corpse.kind],h=[20,18,22,32][corpse.kind];rect(c,corpse.x-w/2,corpse.y-h/4,w,h/2,'#2b3238');rect(c,corpse.x-w/4,corpse.y-h/3,w/2,4,'#3a444c')}
export function machineHuntBiome(scroll,y){return ((Math.floor((scroll+550-y)/2880)%4)+4)%4}
export function drawMachineHuntCanopy(c,tree,hero,biome){const colors=[['#2f4f1d','#3c6326'],['#22402a','#2e5236'],['#5d7a68','#6f8f7a'],['#7d8a3e','#93a04a']][biome],under=Math.hypot(hero.x-tree.x,hero.y-tree.y)<tree.r*.85;c.globalAlpha=under?.7:.92;c.fillStyle=colors[0];c.beginPath();c.ellipse(tree.x,tree.y-8,tree.r,tree.r*.85,0,0,Math.PI*2);c.fill();c.fillStyle=colors[1];c.beginPath();c.ellipse(tree.x-tree.r*.2,tree.y-12,tree.r*.62,tree.r*.5,0,0,Math.PI*2);c.fill();c.globalAlpha=1}
