export function machineHuntLootDrops(robot,random=Math.random){const chance=random(),kind=chance<.32?'heal':chance<.58?'power':chance<.68?'speed':chance<.75?'ward':chance<.84?'stamina':null,drops=kind?[{x:robot.x,y:robot.y,kind}]:[];if(robot.kind===3)drops.push({x:robot.x,y:robot.y,kind:'ward'},{x:robot.x+14,y:robot.y+6,kind:'stamina'},{x:robot.x-14,y:robot.y+6,kind:'heal'});return drops}
// Committed attacks keep their aim through a visible warning and recovery.
