 if(r.mode==='windup'){if(r.modeTime<=1e-9){const a=Math.atan2(hero.y-r.y,hero.x-r.x),speed=r.kind===2?360:312;r.vx=Math.cos(a)*speed;r.vy=Math.sin(a)*speed;r.mode='lunge';r.modeTime=(r.kind===2?17:14)/60;}return true;}
