 const types=[{name:'WATCHER',hp:3,value:25,color:'#a6b6aa'},{name:'STRIDER',hp:5,value:25,color:'#d0bb91'},{name:'SAWTOOTH',hp:12,value:60,color:'#c78c6e'},{name:'THUNDERJAW',hp:30,value:150,color:'#d4b78b'}];
 function reset(){hero={x:160,y:550,hp:5};robots=[];arrows=[];shots=[];reticles=[];scroll=0;score=0;invuln=0;nextBand=1;fire=0;roll=0;rollCd=0;rollDuration=.25;rollSpeed=276;stamina=100;gameOver=0;elapsed=0;power=0;kills=0;loot=[];banner=0;rollX=1;rollY=0;face=1;ward=0;speedBuff=0;staminaMax=100;crates=[];hidden=false;manualScore=0;pendingRecord=false;lastMeters=0;lastMoveX=0;lastMoveY=0;lastMoveAt=-Infinity;aimTarget=null;aimTime=0;aiState='trek';aiGoal=null;aiHide=0;drawingAuto=false;grassPatches=[];treeObjects=[];rockObjects=[];corpses=[];migration={phase:'calm',timer:0,next:250};}reset();
