  const count=(lo,hi)=>lo+Math.floor(Math.random()*(hi-lo+1));
  for(let i=0,n=count(2,3);i<n;i++)grassPatches.push({x:rand(48,272),y:screenY(top-rand(20,220)),r:rand(26,40),band:nb});
  for(let i=0,n=count(1,2);i<n;i++)treeObjects.push({x:rand(40,280),y:screenY(top-rand(24,216)),r:rand(20,30),band:nb});
  if(Math.random()<.8)rockObjects.push({x:rand(30,290),y:screenY(top-rand(16,224)),r:rand(8,13),band:nb});
  const make=(kind,x,d)=>robots.push({x,y:screenY(d),hp:types[kind].hp,kind,phase:rand(0,6),cool:rand(1,2),pounce:0,band:nb});
  if(nb%8===5)crates.push({x:rand(60,260),y:screenY(worldDistance())});
